  str_homeland_secret_msg_10187 = "Kabarnya, Odi putus sekolah gara-gara gagal masuk sekolah yang dia inginkan di Illumina.",
  str_homeland_secret_msg_10188 = "Sebenarnya Barbara sangat pemarah. Terakhir kali, dia memukul seorang penggemar sampai-sampai orang itu lari sambil menangis.",
  str_homeland_secret_msg_10189 = "Kelihatannya Barbara benci sashimi. Dia langsung kabur kalau melihatnya.",
  str_homeland_secret_msg_10190 = "Semua tanda tangan Barbara sudah dicetak! Aku tidak mencintainya lagi!",
  str_homeland_secret_msg_10191 = "Kudengar Sinsa menyerahkan Rediesel Wrench kepada Brock.",
  str_homeland_secret_msg_10192 = "Brock suka bersih-bersih dan merapikan barang. Dia bahkan keluar sebagai juara pertama di Rediesel Wrench.",
  str_homeland_secret_msg_10193 = "Brock tak pernah sakit. Begitulah kalau orang bodoh...",
  str_homeland_secret_msg_10194 = "Brock pernah berkencan dengan seorang anggota Rediesel Wrench di Lumopolis.",
  str_homeland_secret_msg_10195 = "Ophina itu kaya raya. Dia punya tambang permata yang berharga di Northland.",
  str_homeland_secret_msg_10196 = "Meskipun pendek, tubuh Ophina berat... Berat badannya hampir sama dengan rumah ini.",
  str_homeland_secret_msg_10197 = "Jangan pernah memegang tanduk Ophina, ya. Dia bakal berubah menjadi orang yang berbeda di hadapanmu!",
  str_homeland_secret_msg_10198 = "Aku melihat Pact bermain dengan roda di atap... Sepertinya roda itu hidup...",
  str_homeland_secret_msg_10199 = "Kelihatannya Pact berniat menggantikan Victoria sebagai pemimpin True Order!",
  str_homeland_secret_msg_10200 = "Kalau sangat lapar, Pact bisa melahap habis seluruh rumah!",
  str_homeland_secret_msg_10201 = "Darah Nails berwarna putih!",
  str_homeland_secret_msg_10202 = "Nails adalah saudara Victoria yang sudah lama hilang. Itu sebabnya dia selalu mematuhi Victoria...",
  str_homeland_secret_msg_10203 = "Kudengar Wendy bisa membuat misil di tengah badai gurun!",
  str_homeland_secret_msg_10204 = "Wendy bertahan hidup dengan berpura-pura mati di banyak kesempatan!",
  str_homeland_secret_msg_10205 = "Wendy tak bisa terbang. Dia mengandalkan Jetpack untuk melakukannya.",
  str_homeland_secret_msg_10206 = "Pepi sangat ingin bergabung dengan True Order. Dia berkali-kali mengirimkan lamarannya.",
  str_homeland_secret_msg_10207 = "Syal Pepi adalah \"Speaker\" yang dia gunakan.",
  str_homeland_secret_msg_10208 = "Tempo hari, kulihat Pepi dan Victoria di Living Quarters. Sepertinya mereka akrab.",
  str_homeland_secret_msg_10209 = "Sariel membeli beberapa ratus pasang kaus kaki yang sama agar dia bisa menggantinya tepat waktu kalau kaus kakinya sobek.",
  str_homeland_secret_msg_10210 = "Tempo hari, kulihat Sariel memasak makanan dengan air hitam...",
  str_homeland_secret_msg_10211 = "Dulunya orang tua Sariel adalah bangsawan Lumopolis!",
  str_homeland_secret_msg_10212 = "Sejak Eicy pindah ke Dorm, terdengar suara jeritan aneh pada malam hari...",
  str_homeland_secret_msg_10213 = "Sepertinya Eicy adalah putri Victoria. Itu sebabnya dia mematuhi Victoria.",
  str_homeland_secret_msg_10214 = "Eicy bisa membuat semua orang mau mengikuti perintahnya kalau dia melepas penutup matanya.",
  str_homeland_secret_msg_10215 = "Kabarnya, Eicy selalu mengunjungi Navigator saat larut malam...",
  str_homeland_secret_msg_10216 = "Beberapa bulan lalu, Migard berusaha tinggal dengan Navigator untuk sesaat. Itu sebabnya dia tahu banyak soal kaum Caelestite.",
  str_homeland_secret_msg_10217 = "Kau dengar suara gemeresik yang mengerikan itu? Sepertinya asalnya dari hewan peliharaan Migard.",
  str_homeland_secret_msg_10218 = "Migard pernah ingin menderek Soroz ke Illumina dan membongkarnya.",
  str_homeland_secret_msg_10219 = "Sepertinya Migard ingin menjadikan Living Quarters sebagai lab... Astaga...",
  str_homeland_secret_msg_10220 = "Beberapa hari lalu, Corax mencuci tangannya semalaman. Ada apa, ya...?",
  str_homeland_secret_msg_10221 = "Sebenarnya Corax adalah tukang reparasi. Dialah orang yang memperbaiki Colossus terakhir kali.",
  str_homeland_secret_msg_10222 = "Tangan Corax sedingin es... tak seperti orang hidup.",
  str_homeland_secret_msg_10223 = "Benny jauh lebih hebat ketimbang Curo dalam pertarungan!",
  str_homeland_secret_msg_10224 = "Skor menembak Curo jauh lebih tinggi daripada skor Benny.",
  str_homeland_secret_msg_10225 = "Beberapa hari lalu, Benny dan Curo melamar Navigator. Mereka bilang Navigator adalah \"target\" keduanya...",
  str_homeland_secret_msg_10226 = "Cuscuta tak suka tidur di ranjang, jadi dia selalu tidur di alam liar.",
  str_homeland_secret_msg_10227 = "Aneh sekali tukang kebun hebat seperti Cuscuta hanya menanam bunga mawar hitam...",
  str_homeland_secret_msg_10228 = "Sepertinya Cuscuta punya perasaan khusus untuk Navigator...",
  str_homeland_secret_msg_10229 = "Areia bakal roboh kalau duri-duri di tubuhnya dipetik.",
  str_homeland_secret_msg_10230 = "Pedang ajaib Areia bisa bicara. Katanya, ia tumbuh besar dengan Areia.",
  str_homeland_secret_msg_10231 = "Beberapa hari lalu, kulihat Navigator menangis di depan Areia...",
  str_homeland_secret_msg_10232 = "Kotak kecil Sikare berisi petunjuk ke harta karun keluarganya...",
  str_homeland_secret_msg_10233 = "Kudengar Sikare sudah menikah! Benarkah?",
  str_homeland_secret_msg_10234 = "Kelihatannya \"Snowball\" adalah nama anjing yang pernah dipelihara Sikare.",
  str_homeland_secret_msg_10235 = "Tadi kulihat Beverly dan Charon sedang mendiskusikan drama bersama-sama!",
  str_homeland_secret_msg_10236 = "Beberapa hari lalu, aku melihat Navigator terbang berkeliling, mengendarai tombak petir yang Beverly panggil!",
  str_homeland_secret_msg_10237 = "Sepertinya tombak Carleen dibuat oleh Beverly.",
  str_homeland_secret_msg_10238 = "Kelihatannya Constantine pernah ke Northland. Dia bahkan menjadi pengawal Ratu Bethlehem.",
  str_homeland_secret_msg_10239 = "Sebenarnya Constantine tak tahu cara menggunakan senapan. Biasanya, dia hanya menyerang musuh dengan pangkal senapannya.",
  str_homeland_secret_msg_10240 = "Lester pernah pergi ke berbagai tempat, termasuk ke Far East!",
  str_homeland_secret_msg_10241 = "Lester memanggil semua orang dengan sebutan \"Pak\", terlepas dari apa pun jenis kelamin atau usia mereka...",
  str_homeland_secret_msg_10242 = "Kudengar Lester berencana pensiun dari pekerjaannya saat ini dan bekerja sebagai manajer Dorm.",
  str_homeland_secret_msg_10243 = "Tangan Sylva bisa berubah menjadi longsword!",
  str_homeland_secret_msg_10244 = "Sylva bisa mengubah kayu menjadi besi.",
  str_homeland_secret_msg_10245 = "Suara Ansia sangat pelan. Itu sebabnya dia menggunakan pengeras suara.",
  str_homeland_secret_msg_10246 = "Ansia mungkin ingin bergabung dengan Rediesel Wrench, demi musik mereka atau semacamnya.",
  str_homeland_secret_msg_10247 = "Sebenarnya penglihatan Ansia sangat bagus. Dia bahkan bisa melihat warna mata burung dari kejauhan.",
  str_homeland_secret_msg_10248 = "Tessa mahir bertinju. Dia adalah juara sepanjang tahun di Umbraton!",
  str_homeland_secret_msg_10249 = "Semua gigi Tessa adalah gigi palsu. Itu sebabnya dia tidak tanggung-tanggung kalau makan makanan manis!",
  str_homeland_secret_msg_10250 = "Aku melihat Tessa dan Smokey berbelanja di jalan Umbraton. Mereka bahkan minum bersama... Hmmm...",
  str_homeland_secret_msg_10251 = "Kudengar asalkan ada Leah, tak bakal ada kekurangan air bersih di Dorm.",
  str_homeland_secret_msg_10252 = "Beberapa hari lalu, kulihat Navigator melayang dengan gelembung Leah ke puncak bukit di sekitar sini!",
  str_homeland_secret_msg_10253 = "Bunga apa pun yang Leah sentuh akan langsung mekar!",
  str_homeland_secret_msg_10254 = "Terakhir kali, Novio mengira Alice adalah kelinci dan membawanya ke Winter Palace.",
  str_homeland_secret_msg_10255 = "Konon, kedua boneka Alice didapatkannya dari alam liar saat dia tidur berjalan pada suatu hari.",
  str_homeland_secret_msg_10256 = "Alice suka makanan pedas. Dia bahkan bisa menyemburkan api setelahnya!",
  str_homeland_secret_msg_10257 = "Botol air minum di pinggang Sinsa berisi air dingin dan panas untuk Eve.",
  str_homeland_secret_msg_10258 = "Sinsa pandai membuat kebab shish yang lezat. Terakhir kali, dia bahkan mengatakan lebih suka menjadi pedagang kebab shish ketimbang pemimpin.",
  str_homeland_secret_msg_10259 = "Terakhir kali, kulihat Sinsa memaksa Navigator sambil bergumam, \"Kau tak boleh melakukan ini.\"",
  str_homeland_secret_msg_10260 = "Dengar-dengar, Eve pernah mengenakan sesuatu yang spesial untuk Navigator seorang!",
  str_homeland_secret_msg_10261 = "Belakangan ini, Eve sering mengunjungi Seleucid dan hampir memperlakukannya seperti seekor kucing besar.",
  str_homeland_secret_msg_10262 = "Sepertinya Eve mampu mengangkat Soroz hanya dengan satu tangan.",
  str_homeland_secret_msg_10263 = "Terakhir kali, kulihat Eve, Sinsa, dan Navigator sedang piknik bersama. Eve bahkan mengatakan bahwa mereka adalah \"keluarga\" atau semacamnya...",
  str_homeland_secret_msg_10264 = "Tempo hari, Kulihat Dawn memberi Eve bunga. Mereka pasti...",
  str_homeland_secret_msg_10265 = "Red-Eye Gorge itu milik Dawn, tapi diberikan kepada Navigator. Dengar-dengar begitu, sih.",
  str_homeland_secret_msg_10266 = "Dawn pernah memelihara Eclipsite!",
  str_homeland_secret_msg_10267 = "Taki hanya bisa minum segelas anggur.",
  str_homeland_secret_msg_10268 = "Taki datang ke Umbraton karena dia kehilangan semua hartanya gara-gara berjudi di Far East.",
  str_homeland_secret_msg_10269 = "Akhir-akhir ini, Odd Jobs milik Taki sedang sepi pekerjaan. Sebentar lagi, tempat itu pasti bangkrut!",
  str_homeland_secret_msg_10270 = "Belakangan ini, ada lebih banyak kristal merah di Dorm. Memangnya ada yang menang lotre lalu mulai menaruh batu permata di sana-sini, ya?",
  str_homeland_secret_msg_10271 = "Beberapa hari lalu, Beryl menemui Faust. Lalu, terdengar suara-suara aneh dari kamar Faust...",
  str_homeland_secret_msg_10272 = "Menurut gosip, dulunya Beryl adalah bangsawan di Lumopolis. Dia kabur saat keluarganya mengalami suatu masalah.",
  str_homeland_secret_msg_10273 = "Air mata Beryl bisa berubah menjadi batu delima!",
  str_homeland_secret_msg_10274 = "Sepertinya Smokey pernah mengalahkan seekor Manticore dulu! Itu adalah makhluk legendaris!",
  str_homeland_secret_msg_10275 = "Sepertinya Smokey sama sekali tak bisa merasakan sakit.",
  str_homeland_secret_msg_10276 = "Saat Smokey datang ke Umbraton untuk pertama kalinya, dia membakar habis seluruh jalan...",
  str_homeland_secret_msg_10277 = "Smokey punya ratusan pasang kacamata hitam, dan dia mengenakan kacamata yang berbeda setiap hari.",
  str_homeland_secret_msg_10278 = "Kau tahu Giant Lizard yang di Rediesel Wrench, 'kan? Fleur yang menciptakannya, lo!",
  str_homeland_secret_msg_10279 = "Sepertinya Fleur diculik oleh seorang wanita bersenjatakan Revolver, lalu dia diserahkan kepada Rediesel Wrench.",
  str_homeland_secret_msg_10280 = "Kudengar Fleur melarikan diri karena diganggu oleh atasannya di Illumina.",
  str_homeland_secret_msg_10281 = "Kabarnya, rumah Bonacie hancur karena dirinya sendiri.",
  str_homeland_secret_msg_10282 = "Terakhir kali Bonacie mengadakan konser, Soroz sampai bergoyang saat mendengar musiknya.",
  str_homeland_secret_msg_10283 = "Meskipun Bonacie sangat menyukai musik, dia sama sekali tak bisa mengarang musik. Dia hanya pura-pura bisa.",
  str_homeland_secret_msg_10284 = "Genevieve dan Smokey pasti pasangan. Habis mereka selalu bersama, sih.",
  str_homeland_secret_msg_10285 = "Kali terakhir Genevieve mabuk, kudengar dia \"melakukan sesuatu\" pada Navigator di sana, di Dorm...",
  str_homeland_secret_msg_10286 = "Kudengar Genevieve mengubah pelayannya menjadi kuda. Itu sebabnya kuda itu diberi nama \"Anna\"...",
  str_homeland_secret_msg_10287 = "Pasolo memiliki tulisan tangan yang indah. Dia berlatih menulis setiap hari di Dorm. Itu sebabnya dia selalu membawa banyak kertas.",
  str_homeland_secret_msg_10288 = "Beberapa hari yang lalu, ketika Navigator mencoba menceritakan sebuah kisah kepada Pasolo, dia kecewa dan menangis...",
  str_homeland_secret_msg_10289 = "Sejak Pasolo datang ke Dorm, lantainya tidak pernah bersih. Selalu ada potongan kertas di atas lantai di sana-sini!",
  str_homeland_secret_msg_10290 = "Gram bahkan bisa mabuk gara-gara minum soda.",
  str_homeland_secret_msg_10291 = "Gram tampaknya menjadi orang yang memasak semua hidangan yang disajikan di Dorm.",
  str_homeland_secret_msg_10292 = "Kudengar suara mesin mobil bergemuruh semalam. Gram pasti membawa mobilnya keluar untuk berjalan-jalan!",
  str_homeland_secret_msg_10293 = "Menurutku, Revy tidak kuat makan makanan pedas. Aku pernah melihatnya bercucuran air mata seharian penuh setelah mencicipi kue pedas.",
  str_homeland_secret_msg_10294 = "Revy menyebut Navigator sebagai \"orang baik\" untuk terakhir kalinya. Itu artinya...",
  str_homeland_secret_msg_10295 = "Pedang Revy pasti terbuat dari kayu. Bagaimana lagi dia bisa mengangkatnya?",
  str_homeland_secret_msg_10296 = "Kudengar Navigator dan Allura membuka toko barang antik bersama di Umbraton, menjual barang-barang Caelestite dengan harga murah!",
  str_homeland_secret_msg_10297 = "Allura tampaknya telah berinvestasi di Courier Union!",
  str_homeland_secret_msg_10298 = "Kudengar Allura hanya pindah ke Dorm untuk menimbang-nimbang apakah dia harus membeli Dorm atau tidak.",
  str_homeland_secret_msg_10299 = "Paloma dulu bekerja di Lumopolis Temple. Dia diusir karena merusak patung atau semacamnya.",
  str_homeland_secret_msg_10300 = "Pact dan Paloma adalah saudara perempuan yang telah lama hilang!",
  str_homeland_secret_msg_10301 = "Paloma dan Pittman adalah teman sekelas. Mereka sebenarnya saling kenal!",
  str_homeland_secret_msg_10302 = "Beberapa hari yang lalu, aku melihat Navigator berkeliling sambil menunggangi rusa jantan Naroxel. Itu membuat Naroxel marah...",
  str_homeland_secret_msg_10303 = "Naroxel sepertinya bisa berkomunikasi dengan pohon. Pepohonan adalah mata dan telinganya.",
  str_homeland_secret_msg_10304 = "Naroxel sangat takut dingin, jadi dia tidak akan pernah mendekati Northland.",
  str_homeland_secret_msg_10305 = "Tweety ahli dalam perang bola salju! Tidak ada seorang pun di Dorm yang bisa mengalahkannya!",
  str_homeland_secret_msg_10306 = "Tweety memiliki seluruh penginapan di Far East. Ternyata dia kaya!",
  str_homeland_secret_msg_10307 = "Kudengar Tweety pernah ingin membangun asrama dari salju untuk semua orang... Untung tidak jadi.",
  str_homeland_secret_msg_10308 = "Hewan peliharaan Bethel tampaknya telah melahap semua makanan di Dorm.",
  str_homeland_secret_msg_10309 = "Bethel sebenarnya adalah seorang penulis ternama di Umbraton!",
  str_homeland_secret_msg_10310 = "Kudengar Bethel adalah putri Istvan!",
  str_homeland_secret_msg_10311 = "Waktu itu aku melihat Luke membuat sketsa Navigator. Sketsanya mendapat perhatian penuh dari Navigator.",
  str_homeland_secret_msg_10312 = "Begitu Luke mengenakan jaketnya, dia bisa berubah menjadi kupu-kupu dan terbang tinggi.",
  str_homeland_secret_msg_10313 = "Jangan pernah mencoba menangkap kupu-kupu. Luke akan mengirim tentara bayaran untuk mengurusmu.",
  str_homeland_secret_msg_10314 = "Pittman biasa bertarung di Underground Arena dengan Tessa di Umbraton. Dia bahkan pernah menjadi juara.",
  str_homeland_secret_msg_10315 = "Pittman kehilangan lengannya akibat serangan Eclipsite di Umbraton.",
  str_homeland_secret_msg_10316 = "Pittman adalah pembaca cepat. Dia merampungkan banyak berkas setiap hari.",
  str_homeland_secret_msg_10317 = "Kudengar bahwa di Lumopolis, Hedy menghabiskan jutaan Nightium untuk setiap hidangan!",
  str_homeland_secret_msg_10318 = "Beberapa hari yang lalu, Navigator tak sengaja memegang tangan Hedy... dan dihukum berat oleh Pompey karenanya.",
  str_homeland_secret_msg_10319 = "Hedy sepertinya tidak senang dengan Dorm itu. Dia ingin membangun Dorm yang baru.",
  str_homeland_secret_msg_10320 = "Aku melihat Cordy menangis di hadapan Navigator beberapa hari silam, dan dia terus meminta maaf...",
  str_homeland_secret_msg_10321 = "Meskipun Cordy berusia muda, dia adalah sheriff senior di Illumina!",
  str_homeland_secret_msg_10322 = "Seseorang melihat Cordy menyantap tiga porsi makan malam beberapa hari yang lalu.",
  str_homeland_secret_msg_10323 = "Kudengar Hachi dan Gin berencana membeli Soroz. Itu sebabnya mereka ada di sini!",
  str_homeland_secret_msg_10324 = "Jangan pernah menyentuh dagu Hachi. Dia akan panik.",
  str_homeland_secret_msg_10325 = "Gin sepertinya tidak punya ekor...",
  str_homeland_secret_msg_10326 = "Rumah Novio adalah suku barbar jauh di pegunungan Northland.",
  str_homeland_secret_msg_10327 = "Tongkat Novio tampaknya dapat berbicara!",
  str_homeland_secret_msg_10328 = "Winter Palace milik Ratu Bethlehem tampaknya dibangun oleh Novio.",
  str_homeland_secret_msg_10329 = "Lola sebenarnya Aurorian yang berubah menjadi kelinci di Northland!",
  str_homeland_secret_msg_10330 = "Jangan sentuh tanda di leher Lola, atau dia akan memburumu!",
  str_homeland_secret_msg_10331 = "Aku melewati dapur malam itu dan melihat Lola makan sambil tidur...",
  str_homeland_secret_msg_10332 = "Sejak Siobhan pindah ke Dorm, jaring aneh kerap ditemukan di atap...",
  str_homeland_secret_msg_10333 = "Siobhan sebenarnya memang kuno. Itu sebabnya dia sangat tertarik dengan reruntuhan kuno.",
  str_homeland_secret_msg_10334 = "Jangan biarkan Siobhan bersama Gronru. Mereka takkan bisa berbuat apa-apa jika itu terjadi.",
  str_homeland_secret_msg_10335 = "Erica sepertinya sama sekali tidak berasal dari negeri ini. Itu pasti sebabnya dia berbicara dengan cara yang aneh.",
  str_homeland_secret_msg_10336 = "Erica sebenarnya seorang peramal. Dia menubuatkan banyak hal yang kemudian menjadi kenyataan!",
  str_homeland_secret_msg_10337 = "Beberapa hari silam, Erica meramal Navigator. Ramalannya mengatakan bahwa Navigator dan Vice akan...",
  str_homeland_secret_msg_10338 = "Kain aneh yang dikenakan Florine sepertinya dibeli di Illumina.",
  str_homeland_secret_msg_10339 = "Pedang Florine sebenarnya adalah tongkat penyembuh!",
  str_homeland_secret_msg_10340 = "Florine kehilangan ularnya di Dorm...",
  str_homeland_secret_msg_10341 = "Ruby melubangi dinding Dorm saat bermain bisbol... Dia hampir merobohkan Dorm!",
  str_homeland_secret_msg_10342 = "Ruby mungkin seorang penjelajah antusias, tetapi dia buta arah.",
  str_homeland_secret_msg_10343 = "Ruby bilang hamsternya kelak akan menyelamatkan dunia...",
  str_homeland_secret_msg_10344 = "Kudengar hamster Ruby sebenarnya ransum daruratnya pada saat dibutuhkan.",
  str_homeland_secret_msg_10345 = "Rouge sebenarnya seorang vegan. Dia hanya suka aroma daging.",
  str_homeland_secret_msg_10346 = "Rouge tidak terlalu takut dengan hantu. Dia hanya berpura-pura takut demi Ruby.",
  str_homeland_secret_msg_10347 = "Rouge hanya membutuhkan satu jam tidur per hari, jadi dia hanya berpura-pura tidur hampir sepanjang waktu.",
  str_homeland_secret_msg_10348 = "Ada hantu di Dorm! Rinne merasa itu benar setibanya dia di sini!",
  str_homeland_secret_msg_10349 = "Rinne tampaknya mampu meramal hubungan asmara. Terakhir kali, dia bilang Yao dan Amemori akan...",
  str_homeland_secret_msg_10350 = "Jika Kagura Bell milik Rinne berbunyi sendiri, sesuatu yang buruk akan terjadi.",
  str_homeland_secret_msg_10351 = "Rinne tampaknya telah menjadi seorang praktisi di suatu tempat nun jauh.",
  str_homeland_secret_msg_10352 = "Kudengar Kayano telah pindah ke Dorm. Ada yang pernah melihatnya?",
  str_homeland_secret_msg_10353 = "Kayano bukan seorang Aurorian, ya? Kenapa lagi dia begitu takut pada orang lain?",
  str_homeland_secret_msg_10354 = "Kayano tidak berjalan. Dia melayang.",
  str_homeland_secret_msg_10355 = "Amemori perlu tidur lebih dari 16 jam per hari, tetapi dia tetap waspada bahkan ketika sedang tidur.",
  str_homeland_secret_msg_10356 = "Amemori benci bawang putih!",
  str_homeland_secret_msg_10357 = "Amemori bisa menjadi tak kasatmata. Semuanya, hati-hati di Dorm!",
  str_homeland_secret_msg_10358 = "Beberapa hari yang lalu, Yao hampir memakan bantalnya saat tidur. Sumpah, aku melihatnya!",
  str_homeland_secret_msg_10359 = "Yao tidak bisa berenang, tetapi dia bisa mengapung di air dengan sangat baik.",
  str_homeland_secret_msg_10360 = "Bahkan ketika Yao masih kecil, dia mengalahkan ribuan perompak!",
  str_homeland_secret_msg_10361 = "Aku melihat Yao berbagi sepiring \"tahu tidak pedas\" dengan Vice, kemudian...",
  str_homeland_secret_msg_10362 = "Momo diam-diam akan menambah jumlah barang yang dibeli!",
  str_homeland_secret_msg_10363 = "Anzu selalu menggunakan jarinya untuk mencoba sup yang dia masak!",
  str_homeland_secret_msg_10364 = "Kedai ramen Momo dan Anzu membuka cabang di sini!",
  str_homeland_secret_msg_10365 = "Permainan Tourdog menghasilkan banyak uang!",
  str_homeland_secret_msg_10366 = "Saat dalam mode kerja, Tourdog dapat bekerja selama 25 jam per hari!",
  str_homeland_secret_msg_10367 = "Beberapa bangsawan di Lumopolis tampaknya telah berinvestasi pada Tourdog...",
  str_homeland_secret_msg_10368 = "Kudengar Azure akan membekukan orang yang dia suka!",
  str_homeland_secret_msg_10369 = "Makin mabuk Azure, makin baik dia mengemudi!",
  str_homeland_secret_msg_10370 = "Azure selalu mengajak Navigator balapan. Mungkin ia ingin menerima Navigator sebagai muridnya.",
  str_homeland_secret_msg_10371 = "Azure tampaknya menamai mobilnya dengan julukan baru: Caelestite Cutie.",
  str_homeland_secret_msg_10372 = "Roy menyebut robot lebahnya tidak hanya \"Sweetie\", tetapi juga \"Caelee\" dan \"Azurie\"...",
  str_homeland_secret_msg_10373 = "Terakhir kali sistem Firefly macet, Roy menendangnya...",
  str_homeland_secret_msg_10374 = "Aku pernah melihat Roy mengajari Navigator menjahit. Tak kusangka ia punya bakat semacam itu...",
  str_homeland_secret_msg_10375 = "Ransel kucing May awalnya punya dua mata. Entah bagaimana di ranselnya tumbuh dua mata lagi...",
  str_homeland_secret_msg_10376 = "Siapa pun yang diajak bicara kucing putih May akan menerima keberuntungan yang baik!",
  str_homeland_secret_msg_10377 = "Waktu itu, May mengucir dua rambut Navigator. Sungguh menggemaskan!",
  str_homeland_secret_msg_10378 = "Lenore tidak akan bisa bergerak sama sekali jika dia tidak menyentuh telinganya. Dia bilang telinganya adalah \"pegas peregang\" miliknya.",
  str_homeland_secret_msg_10379 = "Beberapa hari yang lalu, aku melihat Lenore tersenyum pada Navigator dan mengundang Navigator ke kamarnya!",
  str_homeland_secret_msg_10380 = "Jika kau perhatikan lebih dekat, Lenore sepertinya tidak punya iris.",
  str_homeland_secret_msg_10381 = "Tanduk di kepala Giles tumbuh. Tanduknya bisa tumbuh setinggi dua lantai!",
  str_homeland_secret_msg_10382 = "Waktu itu aku melihat Giles memelihara burung gagak di Dorm!",
  str_homeland_secret_msg_10383 = "Tak lama setelah Giles pindah, kau bisa mendengar suaranya yang menyeramkan saat dia membaca lirik lagu anak-anak saat malam hari di Dorm...",
  str_homeland_secret_msg_10384 = "Beberapa hari yang lalu, Reinhardt bahkan tidak bisa membuka botol dan harus meminta bantuan Navigator.",
  str_homeland_secret_msg_10385 = "Aku melihat Reinhardt membaca novel roman diam-diam!",
  str_homeland_secret_msg_10386 = "Ada yang pernah lihat foto lama Reinhardt dengan rambut pendek? Dia sangat imut!",
  str_homeland_secret_msg_10387 = "Konon, Reinhardt sebenarnya adalah seorang pria!",
  str_homeland_secret_msg_10388 = "Sinar kematian terpancar dari mata Vice!",
  str_homeland_secret_msg_10389 = "Kudengar Vice sebenarnya memiliki saudara kembar yang mirip sekali dengannya!",
  str_homeland_secret_msg_10390 = "Karena Vice dipromosikan, dia bahkan mengganti koleksi pakaiannya!",
  str_homeland_secret_msg_10391 = "Kudengar {1} akhir-akhir ini sakit, bahkan lengannya jadi aneh...",
  str_homeland_secret_msg_10392 = "Waktu itu, {1} tertawa terbahak-bahak seakan-akan kehilangan kewarasannya di Dorm. Dia berkata bahwa hari untuk menjadi \"General Illumina yang sejati\" sudah dekat... Jadi, siapa General Illumina saat ini?",
  str_homeland_secret_msg_10393 = "Aku melihat {1} menggunakan pedang berujung ganda untuk menangkap ikan, dan dia bahkan memanggang ikan dengan pedang itu!",
  str_homeland_secret_msg_10394 = "Konon, Vice pernah mengira kalau jepit rambutnya hilang, padahal ia memakai jepit itu di bagian belakang kepalanya.",
  str_homeland_secret_msg_10395 = "Konon, Ms. Blanc selalu membawa set minum teh lengkap saat bepergian!",
  str_homeland_secret_msg_10396 = "Konon, Dove punya gudang yang dipenuhi oleh paket yang belum dikirimkan!",
  str_homeland_secret_msg_10397 = "Konon, senjata Raphael seberat seekor kuda!",
  str_homeland_secret_msg_10398 = "Nikinis akan merapikan bunga yang tersemat di kepalanya di depan cermin saat tak ada orang yang melihatnya.",
  str_homeland_secret_msg_10399 = "Konon, Nina adalah penjual senjata!",
  str_homeland_secret_msg_10400 = "Sejak Nina pindah ke sini, warna semua gorden berubah menjadi hitam!",
  str_homeland_secret_msg_10401 = "Konon, Nina sama sekali tak takut pada hantu. Bahkan, ia suka mengobrol dengan mereka!",
  str_homeland_secret_msg_10402 = "Payung Nina selalu terbuka, bahkan saat ia sedang tidur!",
  str_homeland_secret_msg_10403 = "Sanae adalah pengembara dari tempat yang sangat jauh.",
  str_homeland_secret_msg_10404 = "Sanae selalu berbicara sendiri... Apakah dia juga berbicara dalam mimpinya?",
  str_homeland_secret_msg_10405 = "Sejak Sanae dan kakaknya pindah ke sini, ruangan ini jadi terasa ramai sekali...",
  str_homeland_secret_msg_10406 = "Dikatakan bahwa Carleen akan menjadi Penguasa Kota Lumopolis!",
  str_homeland_secret_msg_10407 = "Hanya beberapa malam yang lalu, mata Carleen bersinar!",
  str_homeland_secret_msg_10408 = "Apakah Anda tahu tentang senjata Carleen? Itu terbentuk dari Lumina dan tidak memiliki bentuk fisik.",
  str_homeland_secret_msg_10409 = "Carleen tampaknya telah mendapatkan kemampuan baru. Kudengar dia bisa mengendalikan Lumopolis dan membuatnya terbang kemana-mana.",
  str_homeland_secret_msg_10410 = "Ciel sepertinya telah membuat mecha saat tidur beberapa hari yang lalu.",
  str_homeland_secret_msg_10411 = "Pelindung kaki Ciel tampaknya menjadi bagian dari tubuhnya. Tidak ada yang pernah melihatnya melepasnya.",
  str_homeland_secret_msg_10412 = "Tampaknya Ciel pandai melukis!",
  str_homeland_secret_msg_10413 = "Fia bisa berkomunikasi dengan hewan!",
  str_homeland_secret_msg_10414 = "Pria Kyllo ini disebut-sebut sebagai keluarga Fia!",
  str_homeland_secret_msg_10415 = "Sepertinya Fia bisa berkomunikasi dengan segala macam hal, bahkan rumah ini!",
  str_homeland_secret_msg_10416 = "Sejak Fia pindah, ada banyak item mengkilap. Mungkinkah dia adalah seorang pedagang permata?",
  str_homeland_secret_msg_10417 = "Ramalan Jeno selalu tepat sasaran. Cobalah jika Anda tidak percaya kata-kata saya!",
  str_homeland_secret_msg_10418 = "Tangan Jeno berlubang dan bisa menyembunyikan sesuatu di dalamnya!",
  str_homeland_secret_msg_10419 = "Dikatakan bahwa Jeno memiliki banyak kartu dengan pola yang berbeda, dan setiap kartu mewakili peristiwa besar di masa depan!",
  str_homeland_secret_msg_10420 = "Padahal, Jeno tidak tahu apa-apa tentang trik sulap. Semua yang dia lakukan adalah nyata.",
  str_homeland_secret_msg_10421 = "Rainbow memberi tahu saya bahwa kapal itu memiliki jiwa!",
  str_homeland_secret_msg_10422 = "Saya mendengar orang mengatakan Rainbow adalah keturunan angkatan laut yang melarikan diri dari Illumina!",
  str_homeland_secret_msg_10423 = "Rainbow punya banyak teman! Tapi nama mereka sangat aneh: pancing, papan kayu, dll...",
  str_homeland_secret_msg_10424 = "Pollux adalah malaikat! Seseorang pernah melihat lingkaran cahaya di atas kepalanya.",
  str_homeland_secret_msg_10425 = "Ternyata... Air mata Pollux bisa berubah menjadi permata!",
  str_homeland_secret_msg_10426 = "Pollux tampaknya telah memonopoli banyak bisnis bawah tanah di Umbraton dan bahkan tidak menganggap serius Shadowlord.",
  str_homeland_secret_msg_10427 = "Pollux cukup baik dengan anak-anak.",
  str_homeland_secret_msg_10428 = "Saya mendengar bahwa Casta tidur dengan senapannya di malam hari.",
  str_homeland_secret_msg_10429 = "Terkadang Casta bahkan tidur di bawah tempat tidurnya.",
  str_homeland_secret_msg_10430 = "Casta tampaknya menjadi sangat beruntung baru-baru ini. Dia telah memenangkan permainan menebak jari hampir setiap saat.",
  str_homeland_secret_msg_10431 = "Hakim Jr. sebenarnya adalah orang biasa. Itu sebabnya dia belum dipromosikan selama bertahun-tahun.",
  str_homeland_secret_msg_10432 = "Judge Jr. adalah sosok yang diperankan oleh beberapa orang yang bergiliran memakai topeng berpura-pura menjadi dirinya.",
  str_homeland_secret_msg_10433 = "Hakim Jr. sebenarnya tidak tahu bagaimana mengadili kasus. Dia hanya main-main.",
  str_homeland_secret_msg_10434 = "Mereka bilang Lilica terkenal di Umbraton! Dia datang ke sini untuk menjauh dari penggemar yang memujanya!",
  str_homeland_secret_msg_10435 = "Lilica tampaknya telah membeli asrama ini. Jangan lupa untuk membayar sewanya!",
  str_homeland_secret_msg_10436 = "Lilica datang ke sini berniat untuk membuat film dokumenter tentang cinta dan kebencian yang berkembang di tempat ini...",
  str_homeland_secret_msg_10437 = "Lilica sebenarnya benci akting; dia hanya melakukannya karena pertimbangan untuk penggemarnya.",
  str_homeland_secret_msg_10438 = "Mereka mengatakan Minos berada di geng selama hari-harinya di Umbraton. Lebih baik tetap di sisi baiknya...",
  str_homeland_secret_msg_10439 = "Minos diam-diam memelihara sapi di suatu tempat di asrama. Itu akan menjelaskan moos sesekali di malam hari ...",
  str_homeland_secret_msg_10440 = "Minos tampaknya sangat menyukai cerita hantu.",
  str_homeland_secret_msg_10441 = "Meskipun Minos sangat kuat, dia sebenarnya takut pada serangga! Itu pasti mengapa dia membersihkan semuanya dengan sangat teliti.",
  str_homeland_secret_msg_10442 = "Sadie mungkin kecil, tapi dia sebenarnya sangat kuat! Dia bisa mengambil seluruh rumah!",
  str_homeland_secret_msg_10443 = "Sadie mengatakan dia bermimpi menjadi pemain bisbol bintang dan dia datang ke Cloud Gardens untuk mencari tempat untuk membangun lapangan bisbol!",
  str_homeland_secret_msg_10444 = "Sadie memiliki nafsu makan yang gila! Dia bisa makan seratus potong steak tanpa berkeringat, tidak perlu sayuran!",
  str_homeland_secret_msg_10445 = "Sebenarnya, Axelia tidak bisa bicara. Ini semua adalah pesan yang direkam sebelumnya.",
  str_homeland_secret_msg_10446 = "Axelia terlihat muda, tapi dia adalah pejabat tinggi di Federasi Illumina.",
  str_homeland_secret_msg_10447 = "Sebenarnya Axelia takut dengan serangga.",
  str_homeland_secret_msg_10448 = "Saya perhatikan bahwa tempat tidur Axelia runtuh di bawahnya beberapa hari yang lalu. Mungkinkah dia sangat berat?",
  str_homeland_secret_msg_10449 = "Saya mendengar bahwa Beretta cukup liar dalam pertempuran!",
  str_homeland_secret_msg_10450 = "Rupanya, Beretta adalah Guru Raphael!",
  str_homeland_secret_msg_10451 = "Dua tombak Beretta bisa bergerak sendiri, jadi jangan mendekatinya di malam hari!",
  str_homeland_secret_msg_10452 = "Goldie sepertinya membenci semua hal yang pahit!",
  str_homeland_secret_msg_10453 = "Anjing Goldie juga merupakan bintang besar. Itu membintangi iklan sebelumnya!",
  str_homeland_secret_msg_10454 = "Aku mendengar Goldie berteriak sekali! Saya pikir dia mencoba sesuatu yang terlalu ketat ...",
  str_homeland_secret_msg_10455 = "Jangan sisi buruk Goldie... Meskipun dia terlihat seperti idola malaikat, dia bisa sangat kejam.",
  str_homeland_secret_msg_10456 = "Vic mungkin terlihat muda, tapi sebenarnya dia sudah tua...",
  str_homeland_secret_msg_10457 = "Terakhir kali saya melihat Vic tertidur, dia menangis dengan hewan berbulu di pelukannya, berkata, \"Saya tidak bisa makan lagi ...\"",
  str_homeland_secret_msg_10458 = "Anda dapat mendengar kicauan burung di kamar Vic sepanjang malam. Ini untuk tidur di sekitar sini.",
  str_homeland_secret_msg_10459 = "Vic sama sekali bukan peminum! Binatang buasnya yang menakjubkan biasanya meminum semua minuman keras yang dia simpan.",
  str_homeland_secret_msg_10460 = "Brandy benar-benar pernah memenangkan Turnamen Umbraton Arm Wrestling! Dia sangat kuat!",
  str_homeland_secret_msg_10461 = "Bahkan keluarga Chubb sudah mulai bergosip sejak Brandy tiba.",
  str_homeland_secret_msg_10462 = "Gosip yang selalu dilontarkan Brandy mungkin sebenarnya semuanya benar. Bagaimanapun, dia adalah gadis yang jujur.",
  str_homeland_secret_msg_10463 = "Saya mendengar keluarga Zhong Xu semuanya berubah menjadi kucing!",
  str_homeland_secret_msg_10464 = "Kursi roda Zhong Xu seharusnya bisa terbang!",
  str_homeland_secret_msg_10465 = "Zhong Xu tampaknya tidak memiliki arah. Dia selalu mencari-cari \"kompas\".",
  str_homeland_secret_msg_10466 = "Zhong Xu tidak bisa berjuang untuk menyelamatkan nyawanya. Dulu dia PNS, makanya dia punya banyak benda seni budaya yang masih sedikit.",
  str_homeland_secret_msg_10467 = "Yuebai diduga tidak bisa berenang, jadi bagaimana dia menjadi kapten kapal?",
  str_homeland_secret_msg_10468 = "Aku merasa setiap kali Yuebai tersenyum, sesuatu yang buruk akan terjadi...",
  str_homeland_secret_msg_10469 = "Nama keluarga Yuebai dulunya adalah Sen!",
  str_homeland_secret_msg_10470 = "Yuebai mengenakan baju besi lengkap sepanjang waktu, seolah dia mengira seseorang akan mencoba membunuhnya di malam hari!",
  str_homeland_secret_msg_10471 = "Saya mendengar bahwa Liqing bisa makan apa saja! Dia sangat menyukai semua jenis rumput... Mungkin dia adalah seekor kambing di kehidupan sebelumnya!",
  str_homeland_secret_msg_10472 = "Sebenarnya, obat Liqing disiapkan sesuai dengan ajaran medis masternya. Dia sendiri belum menemukan ide apa pun.",
  str_homeland_secret_msg_10473 = "Liqing rupanya memiliki kucing sebagai saudara laki-laki!",
  str_homeland_secret_msg_10474 = "Nemesis memenangkan Kontes Rap Illumina!",
  str_homeland_secret_msg_10475 = "Nemesis belajar cara berteleportasi dari anggota Courier Union!",
  str_homeland_secret_msg_10476 = "Ternyata semua minuman keras yang diminum Siobhan tidak beralkohol, tapi dia tetap mabuk. Apa yang bisa kukatakan...",
  str_homeland_secret_msg_10477 = "Siobhan datang ke Cloud Gardens untuk menggali patung Colossus yang konon terkubur oleh Caelestites.",
  str_homeland_secret_msg_10478 = "Ternyata Siobhan pernah menjadi bintang film di Umbraton!",
  str_homeland_secret_msg_10479 = "Jeriah tidur dengan ularnya di malam hari... Sungguh mengerikan!",
  str_homeland_secret_msg_10480 = "Rumor mengatakan bahwa Jeriah adalah putri dari suku gurun!",
  str_homeland_secret_msg_10481 = "Sejak Jeriah datang ke sini, asrama menjadi lebih hidup akhir-akhir ini dengan teriakan semua jenis binatang...",
  str_homeland_secret_msg_10482 = "Jeriah tampaknya seorang vegetarian...",
  str_homeland_secret_msg_10483 = "Kya tampaknya memiliki ingatan fotografis! Menakjubkan!",
  str_homeland_secret_msg_10484 = "Meski Kya terlihat tidak bisa diandalkan, nyatanya dia sangat dewasa! Kenapa lagi dia begitu baik dalam pekerjaannya?",
  str_homeland_secret_msg_10485 = "Kya benci dingin, makanya dia selalu mengantarkan surat.",
  str_homeland_secret_msg_10486 = "Benarkah itu Cuscuta membawa keberuntungan bersamanya kemanapun dia pergi?",
  str_homeland_secret_msg_10487 = "Cuscuta sebenarnya mengalami insomnia. Matanya terbuka lebar bahkan ketika dia sedang tidur.",
  str_homeland_secret_msg_10488 = "Pistol air Fia tidak berisi air tapi sesuatu yang bisa membekukanmu seketika!",
  str_homeland_secret_msg_10489 = "Fia sebenarnya memiliki suara yang sangat indah. Banyak orang tidak bisa melupakannya setelah mendengarnya berbicara.",
  str_homeland_secret_msg_10490 = "Fia terkadang membuat suara \"Lo...Lo\". Apakah dia sakit?",
  str_homeland_secret_msg_10491 = "Rasa kantuk Tina itu palsu. Yang benar adalah dia menderita insomnia ...",
  str_homeland_secret_msg_10492 = "Suara dengkuran memenuhi asrama sejak saat itu Tina pindah.",
  str_homeland_secret_msg_10493 = "Sepertinya hal-hal baik terjadi kapan saja Tina membuka matanya.",
  str_homeland_secret_msg_10494 = "Tina pernah bepergian dengan Eclipsite!",
  str_homeland_secret_msg_10495 = "Lihatlah senjata mekanis Leyn. Kudengar Illumina membuatnya untuknya.",
  str_homeland_secret_msg_10496 = "Leyn memiliki saudara laki-laki yang telah lama hilang yang tampaknya berada di Gurun Rediesel.",
  str_homeland_secret_msg_10497 = "saya melihat Leyn dengan beberapa orang dari Rediesel Wrench beberapa hari yang lalu. Apakah dia berpikir untuk membelot ke mereka?",
  str_homeland_secret_msg_10498 = "Leyn telah berbicara dalam tidurnya beberapa kali. Sepertinya dia sangat menginginkan sebuah keluarga.",
  str_homeland_secret_msg_10499 = "Yang benar adalah, Matthieu tidak tahu bagaimana untuk mencoba kasus!",
  str_homeland_secret_msg_10500 = "Sejak Matthieu pindah, seseorang sepertinya membersihkan asrama setiap hari. Kamarnya sangat bersih sekarang.",
  str_homeland_secret_msg_10501 = "Kudengar keluarga Matthieu menjalankan bisnis perhiasan.",
  str_homeland_secret_msg_10502 = "Nyatanya, Hati suka mengoleksi boneka, dan bisa dipastikan banyak sekali yang bisa ditemukan di rumahnya.",
  str_homeland_secret_msg_10503 = "Hati memiliki kecerdasan super tinggi, dan tidak ada teka-teki silang yang tidak bisa dia pecahkan.",
  str_homeland_secret_msg_10504 = "Tampaknya seolah-olah Hati dibesarkan oleh sejenis binatang aneh...?",
  str_homeland_secret_msg_10505 = "Hati sangat pandai memasak! Spesialisasinya adalah semur daging!",
  str_homeland_secret_msg_10506 = "Sejak Kristen pindah, dia telah meminta semua orang untuk melipat selimut mereka menjadi persegi!",
  str_homeland_secret_msg_10507 = "Kristen pernah berlatih dengan tombaknya di kamarnya, sampai dia akhirnya melubangi langit-langit...",
  str_homeland_secret_msg_10508 = "Impian Kristen adalah menjadi pahlawan wanita di sebuah pertunjukan opera!",
  str_homeland_secret_msg_10509 = "Jangan tertipu karena Yingel suka menembak dari jarak jauh. Dia sebenarnya rabun.",
  str_homeland_secret_msg_10510 = "Yingel minum terlalu banyak susu tertentu beberapa hari yang lalu dan cegukan sepanjang malam.",
  str_homeland_secret_msg_10511 = "Tampaknya Yingel akan sakit setelah minum air soda, jadi berhati-hatilah!",
  str_homeland_secret_msg_10512 = "Sejenis burung tampaknya telah membangun sarang di sekitar sini sejak saat itu Yingel pindah.",
  str_homeland_secret_msg_10513 = "Mengejutkan! Leo sebenarnya suka makan daging mentah?!",
  str_homeland_secret_msg_10514 = "Tampaknya Leo membawa bak mandi setiap kali dia berkelahi.",
  str_homeland_secret_msg_10515 = "Tampaknya Leo bisa menggambar peta di kepalanya.",
  str_homeland_secret_msg_10516 = "Dikatakan bahwa ambisi Leo adalah menjadi Penguasa Kota Lumopolis yang baru.",
  str_homeland_secret_msg_10517 = "Jangan ambil sisi buruknya Anatoli. Dia akan mencatatnya di buku catatannya dan menemukan kesempatan untuk membalas dendam.",
  str_homeland_secret_msg_10518 = "Anatoli memiliki penglihatan yang sangat baik, dia dapat melihat sesuatu dengan jelas dari jarak yang sangat jauh, dan dapat membaca gerak bibir...",
  str_homeland_secret_msg_10519 = "Jangan menarik perhatian Anatoli, atau dia akan melakukan apa saja untuk mengamatimu...",
  str_homeland_secret_msg_10520 = "Apakah dia benar-benar tinggal di sini? Aku bahkan belum pernah melihatnya di sekitar sebanyak itu...",
  str_homeland_secret_msg_10521 = "Orang itu tampaknya menjadi lebih muda dari sebelumnya!",
  str_homeland_secret_msg_10522 = "Saya mendengar bahwa Schwartz keluarga memiliki teknik rahasia untuk tetap awet muda! Pantas saja mereka berhasil menguasai Lumopolis begitu lama!",
  str_homeland_secret_msg_10523 = "Dia menjadi sangat kuat akhir-akhir ini! Apakah dia menyelinap ke suatu tempat untuk berlatih?",
  str_homeland_secret_msg_10524 = "Setelah dia tiba, apakah itu imajinasiku, atau kamarnya dipenuhi dengan aroma teh...?",
  str_homeland_secret_msg_10525 = "Seorang putri Lumopolis baru saja pindah!",
  str_homeland_secret_msg_10526 = "Ah! Tampaknya kita memiliki kutu laba-laba.... Dan itu adalah yang besar!",
  str_homeland_secret_msg_10527 = "Saya merasa seolah-olah saya terus mendengar seseorang menelepon \"Carleen, Carleen\" larut malam?",
  str_homeland_secret_msg_10528 = "Sejak Jakine dari Northland pindah, saya sering melihat kilatan cahaya di asrama.",
  str_homeland_secret_msg_10529 = "Ular! Jakine membawa ular ke sini!",
  str_homeland_secret_msg_10530 = "Jakine tidak tidur di malam hari! Dia hanya ingin berpesta sepanjang waktu!",
  str_homeland_secret_msg_20001 = "{1} dan {2} memiliki gaya hidup dan kebiasaan yang sangat berbeda. \"Illumina vs. Lumopolis\" baru akan segera berlangsung di Dorm, camkan kata-kataku.",
  str_homeland_secret_msg_20002 = "{1} ingin jendelanya terbuka, sedangkan {2} ingin jendelanya tertutup. Jadi, mereka terus membuka dan menutup jendela sepanjang malam...",
  str_homeland_secret_msg_20003 = "Sejak {1} pindah, {2} mendengar suara-suara aneh, dan sekarang dia ingin pindah...",
